    if (startX == endX && startY == endY) {
        return true;
    }

    visited[startX][startY] = true;

    for (int[] path : paths) {
        int fromX = path[0];
        int fromY = path[1];
        int toX = path[2];
        int toY = path[3];

        if ((fromX == startX && fromY == startY && !visited[toX][toY]) || (toX == startX && toY == startY && !visited[fromX][fromY])) {
