    int commonCount = 0;
    for (char c : word2.toCharArray()) {
        if (set1.contains(c)) {
            ++commonCount;
            set1.remove(c);
        }
    }

    int sumOfLengths = word1.length() + word2.length();
    int gcd = gcd(commonCount, sumOfLengths);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (sumOfLengths / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
