    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        for (int i = 0; i < 10; i++) {
            bfs(low, high, result, i);
        }

        return result;
    }

    private static void bfs(int low, int high, List<Integer> result, int num) {
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high) {
            return;
        }

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            bfs(low, high, result, num * 10 + lastDigit - 1);
        }
        if (lastDigit < 9) {
            bfs(low, high, result, num * 10 + lastDigit + 1);
        }
    }
}
