public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                graph[i].add(j);
                graph[j].add(i);
            }
        }
    }

    boolean[] visited = new boolean[n];
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count += dfs(graph, visited, i);
        }
    }

    return count;
}

private static int dfs(List<Integer>[] graph, boolean[] visited, int node) {
    visited[node] = true;
    int count = 1;
    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            count += dfs(graph, visited, neighbor);
        }
    }
    visited[node] = false;
    return count;
}
