public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();

    // Traverse the array from the second last digit to the beginning
    for (int i = digits.length - 2; i >= 0; i--) {
        // If the current digit is less than the next digit
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of (i) which is larger than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < digits.length; j++) {
                if (digits[minIndex] > digits[j] && digits[j] > digits[i]) {
                    minIndex = j;
                }
            }

            // Swap the found digit with the digit at i
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the position i to get the smallest possible number
            Arrays.sort(digits, i + 1, digits.length);

            // Convert the digits back to number
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such digit is found, return -1
    return -1;
}

