import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        centerSymmetricNumbersHelper(result, new char[n], 0, n - 1);
        return result;
    }

    private static void centerSymmetricNumbersHelper(List<String> result, char[] current, int left, int right) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        if (left == right) {
            Helper.addIfValid(current, left, '0');
            Helper.addIfValid(current, left, '1');
            Helper.addIfValid(current, left, '8');
        } else {
            Helper.addIfValid(current, left, '0');
            Helper.addIfValid(current, left, '1');
            Helper.addIfValid(current, left, '6');
            Helper.addIfValid(current, left, '8');
            Helper.addIfValid(current, left, '9');
        }
        for (char c : Helper.mirrorMap.keySet()) {
            if (left != right || c != '0') {
                current[left] = c;
                current[right] = Helper.mirrorMap.get(c);
                centerSymmetricNumbersHelper(result, current, left + 1, right - 1);
            }
        }
    }

    private static class Helper {
        private static final Map<Character, Character> mirrorMap = new HashMap<>();

        static {
            mirrorMap.put('0', '0');
            mirrorMap.put('1', '1');
            mirrorMap.put('6', '9');
            mirrorMap.put('8', '8');
            mirrorMap.put('9', '6');
        }

        static void addIfValid(char[] current, int index, char c) {
            if (index == 0 && c == '0' && current.length > 1) {
                return;
            }
            current[index] = c;
            if (index != current.length - 1) {
                current[current.length - 1 - index] = mirrorMap.get(c);
            }
        }
    }
}
